const paths=[...new Set(rows.map(r=>r.path))];
function stats(rs){const m=rs.map(r=>r.ms);return [rs.length, pct(m,50), pct(m,95), pct(m,99), Math.max(...m)];}
print('total rows', rows.length, 'stable', stable.length, 'canary', canary.length);
const sc={}; rows.forEach(r=>{const k=r.version+' '+r.status; sc[k]=(sc[k]||0)+1;});
print('status counts', JSON.stringify(sc));
for(const p of paths){
  print('PATH', p, 'stable[n,p50,p95,p99,max]', JSON.stringify(stats(stable.filter(r=>r.path===p))), 'canary', JSON.stringify(stats(canary.filter(r=>r.path===p))));
}
// how many canary requests are slow outliers per path
for(const p of paths){
  const c=canary.filter(r=>r.path===p), s=stable.filter(r=>r.path===p);
  const thr=pct(s.map(r=>r.ms),99)*1.5;
  print('OUTLIERS path',p,'thr',thr.toFixed(1),'canary over', c.filter(r=>r.ms>thr).length, '/', c.length, 'stable over', s.filter(r=>r.ms>thr).length, '/', s.length);
}

for (const path of ['/browse','/search','/checkout']) {
  for (const nv of [['stable',stable],['canary',canary]]) {
    const name=nv[0], rs=nv[1];
    const ms = rs.filter(r=>r.path===path).map(r=>r.ms).sort((a,b)=>a-b);
    print(path, name, 'n='+ms.length, 'p50='+pct(ms,50), 'p95='+pct(ms,95), 'p99='+pct(ms,99), 'max='+ms[ms.length-1]);
  }
}
const cb = canary.filter(r=>r.path==='/browse');
const sbAll = stable.filter(r=>r.path==='/browse');
const cslow = cb.filter(r=>r.ms>40);
const sslow = sbAll.filter(r=>r.ms>40);
print('BROWSE >40ms canary', cslow.length, '/', cb.length, ' stable', sslow.length, '/', sbAll.length);
print('canary slow browse times(s)', cslow.map(r=>Math.round(r.t)).join(','));
print('canary slow browse ms', cslow.map(r=>r.ms).join(','));
for (let w=0; w<120; w+=30) {
  const c = canary.filter(r=>r.t>=w&&r.t<w+30).map(r=>r.ms).sort((a,b)=>a-b);
  const s = stable.filter(r=>r.t>=w&&r.t<w+30).map(r=>r.ms).sort((a,b)=>a-b);
  print('WIN', w+'-'+(w+30), 'canary n='+c.length, 'p50='+pct(c,50), 'p95='+pct(c,95), 'p99='+pct(c,99), '| stable n='+s.length, 'p50='+pct(s,50), 'p95='+pct(s,95), 'p99='+pct(s,99));
}
print('non-200 total', rows.filter(r=>r.status!==200).length);

function P(a,p){const s=a.slice().sort((x,y)=>x-y);if(!s.length)return NaN;const i=Math.min(s.length-1,Math.max(0,Math.ceil(p/100*s.length)-1));return s[i];}
function ms(rs){return rs.map(r=>r.ms);}
print('OVERALL stable n='+stable.length+' p50='+P(ms(stable),50)+' p95='+P(ms(stable),95)+' p99='+P(ms(stable),99)+' max='+Math.max(...ms(stable)));
