}
const sb=stable.filter(r=>r.path==='/browse'&&r.ms>40), cb=canary.filter(r=>r.path==='/browse'&&r.ms>40);
print('SLOW browse stable '+sb.length+'/'+stable.filter(r=>r.path==='/browse').length+' ms='+sb.map(r=>r.ms).sort((a,b)=>a-b).join(','));
print('SLOW browse canary '+cb.length+'/'+canary.filter(r=>r.path==='/browse').length+' ms='+cb.map(r=>r.ms).sort((a,b)=>a-b).join(','));
