for(const w of [0,30,60,90]){const sw=stable.filter(r=>r.t>=w&&r.t<w+30), cw=canary.filter(r=>r.t>=w&&r.t<w+30);print('WIN '+w+'-'+(w+30)+' canary n='+cw.length+' p95='+P(ms(cw),95)+' max='+Math.max(...ms(cw))+' | stable n='+sw.length+' p95='+P(ms(sw),95)+' max='+Math.max(...ms(sw)));}

